#include<stdio.h> int main() {    int test;    int a,b;        scanf("%d\n",&test);        for(int i=0;i<test;i++){        scanf("%d %d\n",&a,&b);                if(a==b){            printf("0\n");        }        else if((a/b)*b == a || (b/a)*a==b){            printf("1\n");        }        else{            if(a*b == b || a*b == a){                printf("1\n");            }            else{                printf("2\n");            }        }    }    return 0;}